  color: var(--color-ink);
}

.font-display {
  font-family: var(--font-display);
}

.font-body {
  font-family: var(--font-body);
}

.text-balance {
  text-wrap: balance;
}

.text-pretty {
  text-wrap: pretty;
}

.btn-press {
  transition:
    transform 160ms var(--ease-out-quart),
    background-color 200ms var(--ease-out-quart),
    color 200ms var(--ease-out-quart),
    border-color 200ms var(--ease-out-quart),
    box-shadow 200ms var(--ease-out-quart);
}

.btn-press:active {
  transform: scale(0.96);
}

@media (prefers-reduced-motion: reduce) {
  .btn-press:active {
    transform: none;
  }
}

.reveal {
  opacity: 1;
  transform: none;
  transition:
    opacity 700ms var(--ease-out-expo),
    transform 700ms var(--ease-out-expo);
}

.reveal.is-pending {
  opacity: 0;
  transform: translateY(1.25rem);
}

.reveal.is-visible {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .reveal.is-pending {
    opacity: 1;
    transform: none;
  }
}

.hero-ken {
  animation: hero-ken 28s var(--ease-out-quart) infinite alternate;
}

@keyframes hero-ken {
  from {
    transform: scale(1.04) translate3d(0, 0, 0);
  }
  to {
    transform: scale(1.12) translate3d(-1.5%, -1%, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-ken {
    animation: none;
  }
}

.faq-panel[data-open="false"] {
  grid-template-rows: 0fr;
}

.faq-panel[data-open="true"] {
  grid-template-rows: 1fr;
}

.faq-panel {
  display: grid;
  transition: grid-template-rows 320ms var(--ease-out-quart);
}

.faq-panel > div {
  overflow: hidden;
}

@media (prefers-reduced-motion: reduce) {
  .faq-panel {
    transition: none;
  }
}

